<?php
declare(strict_types=1);define('HWC_SKIP_GLOBAL_SHELL',true);require_once __DIR__.'/config/dynamic_forms.php';
$pdo=role_portal_db();dynamic_forms_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);
if(!$user||!in_array((string)$user['role_code'],['admin','coach'],true)){header('Location: access_denied.php');exit;}
$ctx=security_step17_context($pdo);$forms=dynamic_forms_custom_catalog($pdo,(int)$ctx['organization_id']);$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$isAdmin=(string)$user['role_code']==='admin';
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Custom Data Forms</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f8fd;color:#294036;font-family:Inter,Arial}.head{padding:18px 20px;background:linear-gradient(135deg,#fff,#eef5ff);border-bottom:1px solid #dce5df}.head h1{margin:0;font-size:1.25rem}.head p{margin:5px 0;color:#6d7d74;font-size:.78rem}.actions{margin-top:12px}.btn{display:inline-block;padding:9px 12px;border:1px solid #d7e1db;border-radius:10px;background:#fff;color:#315345;text-decoration:none;font-weight:850;font-size:.72rem}.primary{background:#5744db;color:#fff}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding:16px}.card{padding:16px;border:1px solid #dce6e0;border-radius:16px;background:#fff;box-shadow:0 8px 25px #3442 0}.card h2{margin:0;font-size:1rem}.card p{color:#708078;font-size:.75rem}.meta{display:flex;gap:7px;margin:12px 0}.meta span{padding:5px 8px;border-radius:999px;background:#eef8f2;color:#287348;font-size:.65rem;font-weight:800}.empty{grid-column:1/-1;text-align:center;padding:40px}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><header class="head"><h1>Custom Data Forms</h1><p>Reusable Business OS forms and their live database submissions.</p><?php if($isAdmin):?><div class="actions"><a class="btn primary" href="form_designer.php?create=1">＋ Create New Form</a></div><?php endif?></header><main class="grid"><?php foreach($forms as $f):?><article class="card"><h2><?=$h($f['form_name'])?></h2><p><?=$h($f['description']?:'Custom data collection form')?></p><div class="meta"><span><?=(int)$f['field_count']?> fields</span><span><?=(int)$f['submission_count']?> entries</span></div><a class="btn primary" href="dynamic_form_entry.php?form=<?=$h($f['form_key'])?>">New Entry</a><?php if($isAdmin):?> <a class="btn" href="form_designer.php?form=<?=$h($f['form_key'])?>">Design</a> <a class="btn" href="dynamic_form_responses.php?form=<?=$h($f['form_key'])?>">View Data</a><?php endif?></article><?php endforeach?><?php if(!$forms):?><section class="card empty"><h2>No custom form yet</h2><p>Administrator can create the first reusable data form.</p><?php if($isAdmin):?><a class="btn primary" href="form_designer.php?create=1">Create First Form</a><?php endif?></section><?php endif?></main></body></html>
